AS t("lessonId" text,"page" int,"lessonTitle" text,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $guard$
DECLARE eligible integer; history integer; inserted integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.dadyoom_bh_g1_12_worksheets_60)<>60
 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.dadyoom_bh_g1_12_worksheets_60)<>12
 OR (SELECT count(DISTINCT (lesson_id,activity_order)) FROM pg_temp.dadyoom_bh_g1_12_worksheets_60)<>60
 OR EXISTS(SELECT 1 FROM pg_temp.dadyoom_bh_g1_12_worksheets_60 WHERE
  length(content->>'originalReference')<240 OR length(prompt)<15
  OR content ? 'correct' OR content ? 'answer' OR answer IS NULL
  OR activity_order NOT BETWEEN 2 AND 6
  OR (activity_type='multiple_choice' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(content->'options') o WHERE o=answer->>'correct'))
  OR (activity_type='fill_blank' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(content->'items'->0->'options') o WHERE o=answer->'answers'->>0)))
 THEN RAISE EXCEPTION 'Invalid 12 distinct original worksheet exercises'; END IF;
 SELECT count(DISTINCT l.id) INTO eligible FROM public.lessons l
 JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.dadyoom_bh_g1_12_worksheets_60 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE l.status='published' AND g.grade_number=1 AND co.code='BH' AND l.source_pdf_url IS NOT NULL
 AND (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published)=1
 AND (SELECT max(a.activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id)=1
 AND l.content LIKE '%إثراء ضاديوم الأصلي%' AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 IF eligible<>12 THEN RAISE EXCEPTION 'Worksheet lesson scope or learner-history changed: % / 12',eligible; END IF;
 IF EXISTS (SELECT 1 FROM public.lesson_activities WHERE content->>'origin'='DADYOOM_BH_G1_12_WORKSHEETS_60_ORIGINAL_SEMANTIC_20261030')
 THEN RAISE EXCEPTION 'Idempotency: original worksheet exercise batch already inserted'; END IF;
 INSERT INTO public.lesson_activities
 (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'اقرأ بطاقة ضاديوم الأصلية أو استمع إليها مع المعلم، ثم أجب. هذه تدريبات إثرائية مستقلة.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.dadyoom_bh_g1_12_worksheets_60 t ON t.lesson_id=l.id AND t.source_page=l.source_page_start AND t.lesson_title=l.title
 WHERE l.status='published' AND g.grade_number=1 AND co.code='BH'
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>60 THEN RAISE EXCEPTION 'Atomic rollback, inserted % / 60 activities',inserted; END IF;
 RAISE NOTICE 'DADYOOM_BH_G1_ORIGINAL_WORKSHEET_EXERCISES=60';
END $guard$;
COMMIT;